import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.Cs5aHXsR.js";var i=JSON.parse(`{"title":"What is healthchecks-mcp?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1787821181000}`),a={name:`guide/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="what-is-healthchecks-mcp" tabindex="-1">What is healthchecks-mcp? <a class="header-anchor" href="#what-is-healthchecks-mcp" aria-label="Permalink to “What is healthchecks-mcp?”">​</a></h1><p>An MCP server for <a href="https://healthchecks.io" target="_blank" rel="noreferrer">Healthchecks</a>, the dead man&#39;s switch for cron jobs and scheduled tasks. Healthchecks works the other way round from an uptime monitor: instead of polling your service, it waits for your job to check in, and raises an alarm when the ping does not arrive. This server puts that data — and the ability to change it — inside an MCP client.</p><p>It speaks the Management API v3 and works the same against the hosted service and against a self-hosted instance.</p><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>Because the interesting question is never &quot;is anything red&quot;. You can see that on the dashboard. The interesting question is the next one: <em>what did it print when it failed</em>, <em>when did it start</em>, <em>has it been flapping</em>, <em>and does the check even have the right schedule</em>. Answering it means the ping list, then one ping&#39;s body, then the flip history — three lookups that a model can chain in one turn and a person does by clicking.</p><p>The second reason is quieter. Healthchecks has a handful of edges that are easy to get wrong and silent when you do: <code>schedule</code> discards <code>timeout</code> without saying so, <code>tags</code> are space-separated while keyword filters are comma-separated, <code>channels</code> replaces rather than merges, and a check created without <code>channels</code> alerts nobody at all. This server refuses the combinations that lose data and defaults the one that matters, instead of forwarding the mistake.</p><h2 id="what-it-is-not" tabindex="-1">What it is not <a class="header-anchor" href="#what-it-is-not" aria-label="Permalink to “What it is not”">​</a></h2><ul><li><strong>It is not a pinger.</strong> No tool here calls a ping URL. Pinging is a job&#39;s statement that it ran; a tool that could ping would let a model — or text a model happened to read — report success for something that never executed, and a monitoring system that can be talked into green is worse than no monitoring.</li><li><strong>It is not a Healthchecks administrator.</strong> Projects, members, ping keys and notification integrations are configured in the web UI; the Management API has no endpoints for them. <code>list_integrations</code> reads them so the write tools can refer to them by UUID.</li><li><strong>It is not a multi-project view.</strong> A Healthchecks API key belongs to exactly one project. To reach two, run two instances of this server with two keys.</li><li><strong>It is not an archive.</strong> The instance keeps 100 pings per check on a free plan and 1000 on a paid one, with no pagination and no way to reach past that, and flips only go back to the start of the month before last.</li></ul>`,8)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};